    // Load restaurants by destination
    function loadRestaurantsByDestination() {
        const destination = document.getElementById('mealDestination').value;
        const restaurantSelect = document.getElementById('mealRestaurant');
        
        if (!restaurantSelect) return;
        
        // Get all restaurant options
        const allRestaurants = @json($restaurants);
        
        // Clear current options
        restaurantSelect.innerHTML = '<option value="">Select Restaurant</option>';
        
        // If no destination selected, don't show any restaurants
        if (!destination) {
            restaurantSelect.innerHTML = '<option value="">Select a destination first</option>';
            return;
        }
        
        // Filter restaurants based on destination (city field)
        const selectedDest = destination.toLowerCase().trim();
        const filteredRestaurants = allRestaurants.filter(restaurant => {
            // Check if restaurant's city matches the selected destination
            const restaurantCity = (restaurant.city || '').toLowerCase().trim();
            return restaurantCity === selectedDest;
        });
        
        // Add filtered restaurants to the dropdown
        if (filteredRestaurants.length === 0) {
            restaurantSelect.innerHTML = '<option value="">No restaurants available for ' + destination + '</option>';
            console.log('No restaurants found for destination: ' + destination);
            return;
        }
        
        filteredRestaurants.forEach(restaurant => {
            const option = document.createElement('option');
            option.value = restaurant.restaurant_id; // Use numeric ID directly
            option.textContent = restaurant.name;
            option.setAttribute('data-name', restaurant.name);
            option.setAttribute('data-type', 'restaurant');
            option.setAttribute('data-restaurant-id', restaurant.restaurant_id);
            option.setAttribute('data-zone-id', restaurant.zone_id || '');
            option.setAttribute('data-city', restaurant.city || '');
            option.setAttribute('data-country', restaurant.country || '');
            restaurantSelect.appendChild(option);
        });
        
        console.log(`Loaded ${filteredRestaurants.length} restaurant(s) for ${destination}`);
    }
    
    // Update meals from selected restaurant
    async function updateMealsFromRestaurant() {
        const restaurantSelect = document.getElementById('mealRestaurant');
        let restaurantId = restaurantSelect.value;
        
        if (!restaurantId) {
            alert('Please select a restaurant first');
            return;
        }
        
        // Extract numeric ID if value is in format "restaurant_X"
        if (restaurantId.startsWith('restaurant_')) {
            restaurantId = restaurantId.replace('restaurant_', '');
        }
        
        // Also try to get from data attribute as fallback
        if (!restaurantId || isNaN(restaurantId)) {
            const selectedOption = restaurantSelect.options[restaurantSelect.selectedIndex];
            restaurantId = selectedOption.getAttribute('data-restaurant-id') || restaurantId;
        }
        
        // Validate that we have a numeric ID
        if (!restaurantId || isNaN(restaurantId)) {
            alert('Invalid restaurant ID. Please select a restaurant again.');
            return;
        }
        
        const restaurantName = restaurantSelect.options[restaurantSelect.selectedIndex].getAttribute('data-name');
        
        // Get DMC ID
        const dmcId = '{{ $dmc_id ?? "" }}';
        if (!dmcId) {
            alert('DMC ID not found. Please refresh the page.');
            return;
        }
        
        // Show loading state
        const mealsTableBody = document.getElementById('mealsTableBody');
        if (mealsTableBody) {
            mealsTableBody.innerHTML = '<tr><td colspan="9" class="text-center" style="padding: 20px;">Loading meals...</td></tr>';
        }
        
        try {
            // Build the URL with numeric restaurant ID
            const url = `{{ route('fetch-meals-by-restaurant') }}?restaurant_id=${restaurantId}`;
            console.log('Fetching meals from URL:', url);
            
            // Fetch meals from web route (uses session auth, better for Blade templates)
            const response = await fetch(url, {
                method: 'GET',
                headers: {
                    'Accept': 'application/json',
                    'Content-Type': 'application/json',
                    'X-CSRF-TOKEN': document.querySelector('meta[name="csrf-token"]')?.getAttribute('content') || '{{ csrf_token() }}',
                    'X-Requested-With': 'XMLHttpRequest'
                },
                credentials: 'same-origin'
            });
            
            console.log('Response status:', response.status, response.statusText);
            console.log('Response headers:', Object.fromEntries(response.headers.entries()));
            
            // Get response text first to check what we actually received
            const responseText = await response.text();
            console.log('Response text (first 500 chars):', responseText.substring(0, 500));
            
            // Check if response is OK
            if (!response.ok) {
                console.error('API request failed:', response.status, response.statusText);
                console.error('Full error response:', responseText);
                
                // Try to parse as JSON if possible
                let errorMessage = 'Error loading meals. Please try again.';
                try {
                    const errorData = JSON.parse(responseText);
                    errorMessage = errorData.message || errorMessage;
                } catch (e) {
                    // If not JSON, it's probably an HTML error page
                    if (response.status === 401 || response.status === 403) {
                        errorMessage = 'Authentication required. Please refresh the page and try again.';
                    } else if (response.status === 404) {
                        errorMessage = 'Route not found. Please check the route configuration.';
                    } else if (response.status === 500) {
                        errorMessage = 'Server error. Please check the server logs.';
                    } else {
                        errorMessage = `Server returned HTML instead of JSON (Status: ${response.status}). This usually means an authentication or routing error.`;
                    }
                }
                
                if (mealsTableBody) {
                    mealsTableBody.innerHTML = `<tr><td colspan="9" class="text-center text-danger" style="padding: 20px;">${errorMessage}</td></tr>`;
                }
                alert(errorMessage);
                return;
            }
            
            // Check if response is JSON
            const contentType = response.headers.get('content-type') || '';
            if (!contentType.includes('application/json')) {
                console.error('Expected JSON but received:', contentType);
                console.error('Response text:', responseText.substring(0, 500));
                const errorMessage = 'Server returned non-JSON response. This usually indicates an authentication or routing error.';
                if (mealsTableBody) {
                    mealsTableBody.innerHTML = `<tr><td colspan="9" class="text-center text-danger" style="padding: 20px;">${errorMessage}</td></tr>`;
                }
                alert(errorMessage + '\n\nCheck the browser console for details.');
                return;
            }
            
            // Parse JSON
            let data;
            try {
                data = JSON.parse(responseText);
            } catch (e) {
                console.error('Failed to parse JSON:', e);
                console.error('Response text:', responseText);
                throw new Error('Invalid JSON response from server');
            }
            
            // Check for success flag and error messages
            if (!data.success) {
                const errorMessage = data.message || 'Error loading meals. Please try again.';
                if (mealsTableBody) {
                    mealsTableBody.innerHTML = `<tr><td colspan="9" class="text-center text-muted" style="padding: 20px;">${errorMessage}</td></tr>`;
                }
                alert(errorMessage);
                return;
            }
            
            // Process meals from API response
            // Web route returns { success: true, meals: [...] }
            const restaurantMeals = data.meals || [];
            if (restaurantMeals.length === 0) {
                if (mealsTableBody) {
                    mealsTableBody.innerHTML = '<tr><td colspan="9" class="text-center text-muted" style="padding: 20px;">No meals/dishes found for this restaurant</td></tr>';
                }
                alert('No meals/dishes found for this restaurant');
                return;
            }
            
            // Process meals
            processRestaurantMeals(restaurantMeals, restaurantName, restaurantId);
            
        } catch (error) {
            console.error('Error fetching meals for restaurant:', error);
            console.error('Error stack:', error.stack);
            if (mealsTableBody) {
                mealsTableBody.innerHTML = '<tr><td colspan="9" class="text-center text-danger" style="padding: 20px;">Error loading meals. Please check the console for details.</td></tr>';
            }
            alert('Error loading meals: ' + error.message + '\n\nCheck the browser console for more details.');
        }
    }
    
    // Process restaurant meals and populate table
    function processRestaurantMeals(restaurantMeals, restaurantName, restaurantId) {
        // Get the meals table body
        const mealsTableBody = document.getElementById('mealsTableBody');
        if (!mealsTableBody) return;
        
        // Clear existing rows
        mealsTableBody.innerHTML = '';
        
        // Count meals by type for summary
        let breakfastCount = 0, lunchCount = 0, dinnerCount = 0;
        
        // Debug: Log all meals to see their structure
        console.log('All meals from restaurant:', restaurantMeals);
        
        // Add new rows for each meal/dish
        restaurantMeals.forEach((meal, index) => {
            // Determine meal type/period
            // API returns: 'Breakfast', 'Lunch', 'Dinner' as strings, or 1, 2, 3 as numbers
            let mealType = 'dinner'; // default
            let originalType = meal.meal_period || meal.type || '';
            
            // Convert to string for comparison
            let typeValue = String(originalType).trim();
            
            console.log(`Meal: "${meal.name}", Original Type: "${originalType}" (${typeof originalType}), Type Value: "${typeValue}"`);
            
            // Map values to meal types
            if (typeValue === '1' || typeValue.toLowerCase() === 'breakfast' || typeValue.toLowerCase() === 'bf') {
                mealType = 'breakfast';
                breakfastCount++;
            } else if (typeValue === '2' || typeValue.toLowerCase() === 'lunch' || typeValue.toLowerCase() === 'l') {
                mealType = 'lunch';
                lunchCount++;
            } else if (typeValue === '3' || typeValue.toLowerCase() === 'dinner' || typeValue.toLowerCase() === 'd') {
                mealType = 'dinner';
                dinnerCount++;
            } else {
                // Fallback: Try to guess from meal name
                const mealNameLower = (meal.name || '').toLowerCase();
                if (mealNameLower.includes('breakfast') || mealNameLower.includes('morning') || mealNameLower.includes('bf')) {
                    mealType = 'breakfast';
                    breakfastCount++;
                } else if (mealNameLower.includes('lunch') || mealNameLower.includes('afternoon')) {
                    mealType = 'lunch';
                    lunchCount++;
                } else if (mealNameLower.includes('dinner') || mealNameLower.includes('evening')) {
                    mealType = 'dinner';
                    dinnerCount++;
                } else {
                    // Default to dinner if we can't determine
                    mealType = 'dinner';
                    dinnerCount++;
                }
            }
            
            const row = document.createElement('tr');
            row.className = 'meal-row';
            row.setAttribute('data-meal-id', meal.meal_id);
            row.setAttribute('data-meal-name', meal.name);
            row.setAttribute('data-meal-type', mealType);
            row.setAttribute('data-restaurant-id', restaurantId);
            row.setAttribute('data-restaurant-name', restaurantName);
            
            // Parse prices from database - both cost and sell should be the same value from database
            const adultPrice = parseFloat(meal.adult_price || meal.price || 0).toFixed(2);
            const childPrice = parseFloat(meal.child_price || meal.price || 0).toFixed(2);
            
            // Use the same database price for both cost and sell (no calculation)
            const adultCostPrice = adultPrice;
            const adultSellPrice = adultPrice;
            const childCostPrice = childPrice;
            const childSellPrice = childPrice;
            
            // Icon based on meal type
            let mealIcon = 'ri-restaurant-fill';
            let iconColor = 'text-success';
            if (mealType === 'breakfast') {
                mealIcon = 'ri-cup-line';
                iconColor = 'text-warning';
            } else if (mealType === 'lunch') {
                mealIcon = 'ri-restaurant-2-line';
                iconColor = 'text-info';
            } else if (mealType === 'dinner') {
                mealIcon = 'ri-restaurant-fill';
                iconColor = 'text-success';
            }
            
            row.innerHTML = `
                <td style="padding: 2px 8px; text-align: center;">
                    <input type="checkbox" class="meal-checkbox" data-meal-id="${meal.meal_id}" onchange="updateMealTotalAmount()">
                </td>
                <td style="padding: 2px 8px;">
                    <i class="${mealIcon} ${iconColor} me-1" style="font-size: 14px;"></i>
                    ${meal.name}
                    <small class="text-muted ms-2">(${mealType.charAt(0).toUpperCase() + mealType.slice(1)})</small>
                </td>
                <td style="padding: 2px 8px;">
                    <input type="number" class="form-control form-control-sm meal-count" data-meal-id="${meal.meal_id}" value="1" min="0" style="font-size: 10px; padding: 2px 4px; text-align: center;" oninput="updateMealTotalAmount()">
                </td>
                <td style="padding: 2px 8px;">
                    <input type="number" class="form-control form-control-sm meal-adult-qty" data-meal-id="${meal.meal_id}" value="0" min="0" style="font-size: 10px; padding: 2px 4px; text-align: center;" oninput="updateMealTotalAmount()">
                </td>
                <td style="padding: 2px 8px;">
                    <input type="text" class="form-control form-control-sm meal-adult-cost" data-meal-id="${meal.meal_id}" value="SGD ${adultCostPrice}" readonly style="font-size: 10px; padding: 2px 4px; background-color: #f5f5f5;">
                </td>
                <td style="padding: 2px 8px;">
                    <input type="text" class="form-control form-control-sm meal-adult-sell" data-meal-id="${meal.meal_id}" value="SGD ${adultSellPrice}" style="font-size: 10px; padding: 2px 4px;" oninput="updateMealTotalAmount()">
                </td>
                <td style="padding: 2px 8px;">
                    <input type="number" class="form-control form-control-sm meal-child-qty" data-meal-id="${meal.meal_id}" value="0" min="0" style="font-size: 10px; padding: 2px 4px; text-align: center;" oninput="updateMealTotalAmount()">
                </td>
                <td style="padding: 2px 8px;">
                    <input type="text" class="form-control form-control-sm meal-child-cost" data-meal-id="${meal.meal_id}" value="SGD ${childCostPrice}" readonly style="font-size: 10px; padding: 2px 4px; background-color: #f5f5f5;">
                </td>
                <td style="padding: 2px 8px;">
                    <input type="text" class="form-control form-control-sm meal-child-sell" data-meal-id="${meal.meal_id}" value="SGD ${childSellPrice}" style="font-size: 10px; padding: 2px 4px;" oninput="updateMealTotalAmount()">
                </td>
                <td style="padding: 2px 8px;">
                    <input type="number" class="form-control form-control-sm meal-infant-qty" data-meal-id="${meal.meal_id}" value="0" min="0" style="font-size: 10px; padding: 2px 4px; text-align: center;" oninput="updateMealTotalAmount()">
                </td>
                <td style="padding: 2px 8px;">
                    <input type="text" class="form-control form-control-sm meal-infant-cost" data-meal-id="${meal.meal_id}" value="SGD 0.00" readonly style="font-size: 10px; padding: 2px 4px; background-color: #f5f5f5;">
                </td>
                <td style="padding: 2px 8px;">
                    <input type="text" class="form-control form-control-sm meal-infant-sell" data-meal-id="${meal.meal_id}" value="SGD 0.00" style="font-size: 10px; padding: 2px 4px;" oninput="updateMealTotalAmount()">
                </td>
            `;
            
            mealsTableBody.appendChild(row);
        });
        
        // Reset "Select All" checkbox
        const selectAllCheckbox = document.getElementById('selectAllMeals');
        if (selectAllCheckbox) {
            selectAllCheckbox.checked = false;
        }
        
        // Initialize total amount calculation
        updateMealTotalAmount();
        
        // Auto-fill adult/child/infant counts from header for all newly created rows
        const headerValues = getHeaderValues();
        document.querySelectorAll('.meal-adult-qty').forEach(input => {
            if (!input.value || input.value == '0') input.value = headerValues.adults;
            input.setAttribute('max', headerValues.adults);
            // Remove any existing listeners to avoid duplicates
            const newInput = input.cloneNode(true);
            input.parentNode.replaceChild(newInput, input);
            newInput.addEventListener('input', function() {
                if (parseInt(this.value) > headerValues.adults) {
                    this.value = headerValues.adults;
                    alert(`Adults cannot exceed ${headerValues.adults} (header value)`);
                }
            });
        });
        document.querySelectorAll('.meal-child-qty').forEach(input => {
            if (!input.value || input.value == '0') input.value = headerValues.children;
            input.setAttribute('max', headerValues.children);
            // Remove any existing listeners to avoid duplicates
            const newInput = input.cloneNode(true);
            input.parentNode.replaceChild(newInput, input);
            newInput.addEventListener('input', function() {
                if (parseInt(this.value) > headerValues.children) {
                    this.value = headerValues.children;
                    alert(`Children cannot exceed ${headerValues.children} (header value)`);
                }
            });
        });
        document.querySelectorAll('.meal-infant-qty').forEach(input => {
            if (!input.value || input.value == '0') input.value = headerValues.infants;
            input.setAttribute('max', headerValues.infants);
            // Remove any existing listeners to avoid duplicates
            const newInput = input.cloneNode(true);
            input.parentNode.replaceChild(newInput, input);
            newInput.addEventListener('input', function() {
                if (parseInt(this.value) > headerValues.infants) {
                    this.value = headerValues.infants;
                    alert(`Infants cannot exceed ${headerValues.infants} (header value)`);
                }
            });
        });
        
        // Show all meals (no filtering)
        
        // Debug: Log meal type counts
        console.log('Meal Type Summary:', {
            total: restaurantMeals.length,
            breakfast: breakfastCount,
            lunch: lunchCount,
            dinner: dinnerCount
        });
        
        // Show success message with meal type breakdown
        let summaryMessage = `Loaded ${restaurantMeals.length} dish(es) from ${restaurantName}`;
        const breakdown = [];
        if (breakfastCount > 0) breakdown.push(`${breakfastCount} Breakfast`);
        if (lunchCount > 0) breakdown.push(`${lunchCount} Lunch`);
        if (dinnerCount > 0) breakdown.push(`${dinnerCount} Dinner`);
        
        if (breakdown.length > 0) {
            summaryMessage += ` (${breakdown.join(', ')})`;
        }
        
        // Use SweetAlert2 if available, otherwise use console log
        if (typeof Swal !== 'undefined') {
            const Toast = Swal.mixin({
                toast: true,
                position: 'top-end',
                showConfirmButton: false,
                timer: 4000,
                timerProgressBar: true,
            });
            
            Toast.fire({
                icon: 'success',
                title: summaryMessage.replace(' (', '<br><small>(').replace(')', ')</small>')
            });
        } else {
            console.log('✓ ' + summaryMessage);
        }
    }
    
    // Filter meals by type
    function filterMealsByType(type) {
        const rows = document.querySelectorAll('.meal-row');
        
        rows.forEach(row => {
            const rowType = row.getAttribute('data-meal-type');
            row.style.display = (rowType === type) ? '' : 'none';
        });
    }
    
    // Toggle select all meals
    function toggleSelectAllMeals() {
        const selectAll = document.getElementById('selectAllMeals');
        const checkboxes = document.querySelectorAll('.meal-checkbox');
        checkboxes.forEach(cb => cb.checked = selectAll.checked);
    }
    
    // Save and close meals
    async function saveAndCloseMeals() {
        // Check if we're editing an existing meal
        const isEditing = window.editingMealIndex !== undefined && window.editingMealIndex !== null;
        
        const selectedRows = document.querySelectorAll('.meal-checkbox:checked');
        
        if (selectedRows.length === 0 && !isEditing) {
            alert('Please select at least one meal');
            return;
        }
        
        // Get date/time from modal input field
        const dateTimeInput = document.getElementById('mealDateTime');
        console.log('=== saveAndCloseMeals ===');
        console.log('mealDateTime input element:', dateTimeInput);
        console.log('mealDateTime value:', dateTimeInput?.value);
        const dateTime = dateTimeInput?.value || getDefaultServiceDate();
        console.log('Final dateTime to use:', dateTime);
        console.log('isEditing:', isEditing);
        
        if (!dateTime) {
            alert('Please select date/time for the meal');
            return;
        }
        
        // If editing, update the existing meal
        if (isEditing && selectedRows.length > 0) {
            const checkbox = selectedRows[0]; // Only use first selected when editing
            const mealItemId = checkbox.getAttribute('data-meal-id'); // This is the meal item from database
            const row = checkbox.closest('tr');
            const mealName = row.getAttribute('data-meal-name');
            const mealType = row.getAttribute('data-meal-type') || mealName;
            
            // Get values from the row
            const mealCount = parseInt(row.querySelector('.meal-count').value) || 0;
            const adultsQty = parseInt(row.querySelector('.meal-adult-qty').value) || 0;
            const adultCostValue = row.querySelector('.meal-adult-cost')?.value || 'SGD 0.00';
            const adultSellValue = row.querySelector('.meal-adult-sell')?.value || 'SGD 0.00';
            const childQty = parseInt(row.querySelector('.meal-child-qty').value) || 0;
            const childCostValue = row.querySelector('.meal-child-cost')?.value || 'SGD 0.00';
            const childSellValue = row.querySelector('.meal-child-sell')?.value || 'SGD 0.00';
            const infantQty = parseInt(row.querySelector('.meal-infant-qty').value) || 0;
            const infantCostValue = row.querySelector('.meal-infant-cost')?.value || 'SGD 0.00';
            const infantSellValue = row.querySelector('.meal-infant-sell')?.value || 'SGD 0.00';
            
            // Get transfer info from restaurant transfer section (not per-row)
            const transferChecked = document.getElementById('restaurantTransferCheckbox')?.checked || false;
            const transferDestinationSelect = document.getElementById('restaurantTransferDestination');
            const transferDestination = transferDestinationSelect?.value || '';
            // Get destination name from data-name attribute (works with Select2)
            const transferDestinationOption = $('#restaurantTransferDestination').find(':selected');
            const transferDestinationName = transferDestinationOption.attr('data-name') || transferDestinationOption.text() || transferDestination;
            // Get vehicle type name from data attribute instead of value (which is vehicle_id)
            const vehicleTypeSelect = document.getElementById('restaurantTransferVehicleType');
            const vehicleId = vehicleTypeSelect?.value || '';
            const vehicleOption = vehicleTypeSelect?.selectedOptions[0];
            const vehicleType = vehicleOption?.getAttribute('data-type') || 'sedan';
            const vehicleName = vehicleOption?.text || '';
            const vehicleCapacity = parseInt(vehicleOption?.getAttribute('data-seating')) || 0;
            const transferWay = document.getElementById('restaurantTransferWay')?.value || 'one-way';
            const transferType = document.getElementById('restaurantTransferType')?.value || 'S';
            
            console.log('=== Editing Meal - Transfer Status ===');
            console.log('Transfer checkbox checked:', transferChecked);
            console.log('Transfer destination:', transferDestination);
            console.log('Transfer destination name:', transferDestinationName);
            
            // Parse cost and sell prices separately
            const adultCost = parseFloat(adultCostValue.replace(/[^0-9.]/g, '')) || 0;
            const adultSell = parseFloat(adultSellValue.replace(/[^0-9.]/g, '')) || 0;
            const childCost = parseFloat(childCostValue.replace(/[^0-9.]/g, '')) || 0;
            const childSell = parseFloat(childSellValue.replace(/[^0-9.]/g, '')) || 0;
            const infantCost = parseFloat(infantCostValue.replace(/[^0-9.]/g, '')) || 0;
            const infantSell = parseFloat(infantSellValue.replace(/[^0-9.]/g, '')) || 0;
            
            // Get restaurant info from dropdown (source of truth)
            const restaurantSelect = document.getElementById('mealRestaurant');
            const restaurantName = restaurantSelect && restaurantSelect.value 
                ? restaurantSelect.options[restaurantSelect.selectedIndex].getAttribute('data-name') 
                : 'Unknown Restaurant';
            
            // Get old meal and its transfer ID
            const oldMeal = mealList[window.editingMealIndex];
            const mealId = oldMeal.id; // Get existing meal ID
            let transferId = oldMeal.transferId; // Keep existing transfer ID if updating
            
            // Handle transfer update/creation/deletion
            let transferInfo = null;
            let transferEntryId = null;
            
            if (transferChecked && transferDestination) {
                console.log('Creating/updating transfer for restaurant:', restaurantName);
                
                // Get "Is PickUp?" checkbox state
                const isDestinationPickup = document.getElementById('restaurantTransferIsPickup')?.checked || false;
                
                transferInfo = {
                    destination: transferDestinationName,
                    destinationId: transferDestination, // Store destination ID for reliable matching in edit
                    vehicleId: vehicleId,
                    vehicleName: vehicleName,
                    vehicleType: vehicleType,
                    type: transferType,
                    way: transferWay,
                    isDestinationPickup: isDestinationPickup
                };
                
                // Fetch zone price for restaurant transfer (similar to hotel transfers)
                let restaurantZonePrice = { private_price: 0, shared_price: 0 };
                let restaurantTransferCost = 0;
                let restaurantTransferSell = 0;
                
                // Get restaurant ID and destination details for zone price calculation
                const restaurantSelect = document.getElementById('mealRestaurant');
                const actualRestaurantId = restaurantSelect?.value || '';
                const actualDestinationId = transferDestination;
                const destinationType = transferDestinationOption.attr('data-type') || 'hotel';
                const dmcId = '{{ $dmc_id ?? "" }}';
                
                // Determine pickup and dropoff based on checkbox
                let pickupId, pickupType, dropoffId, dropoffType, pickupName, dropoffName;
                if (isDestinationPickup) {
                    // Destination is pickup, Restaurant is dropoff
                    pickupId = actualDestinationId;
                    pickupType = destinationType;
                    pickupName = transferDestinationName;
                    dropoffId = actualRestaurantId;
                    dropoffType = 'restaurant';
                    dropoffName = restaurantName;
                } else {
                    // Restaurant is pickup, Destination is dropoff (default behavior)
                    pickupId = actualRestaurantId;
                    pickupType = 'restaurant';
                    pickupName = restaurantName;
                    dropoffId = actualDestinationId;
                    dropoffType = destinationType;
                    dropoffName = transferDestinationName;
                }
                
                if (vehicleId && pickupId && dropoffId && dmcId) {
                    try {
                        restaurantZonePrice = await fetchZonePrice(
                            vehicleId,
                            pickupId,
                            pickupType,
                            dropoffId,
                            dropoffType,
                            dmcId
                        );
                        
                        // Calculate prices using zone price
                        const prices = calculateTransferPrice(restaurantZonePrice, transferType, transferWay, adultsQty, childQty);
                        restaurantTransferCost = prices.cost || 0;
                        restaurantTransferSell = prices.sell || 0;
                    } catch (error) {
                        console.error('Error fetching zone price for restaurant transfer:', error);
                        // Fallback: keep price as 0
                    }
                }
                
                // Create transfer entry data
                const transferEntry = {
                    dateTime: dateTime,
                    service: `${pickupName} / ${dropoffName}`,
                    restaurantName: restaurantName, // Store restaurant name for entrypickup
                    transportMode: 'local',
                    type: transferType,
                    vehicleId: vehicleId,
                    vehicleName: vehicleName,
                    vehicleType: vehicleType,
                    capacity: vehicleCapacity,
                    way: transferWay,
                    destination: transferDestinationName,
                    destinationId: transferDestination, // Store destination ID for easier lookup when editing
                    pickup: pickupName,
                    dropoff: dropoffName,
                    isDestinationPickup: isDestinationPickup,
                    adults: adultsQty,
                    adultsQty: adultsQty,
                    child: childQty,
                    childQty: childQty,
                    adultCost: restaurantTransferCost,
                    adultSell: restaurantTransferSell,
                    childCost: restaurantTransferCost,
                    childSell: restaurantTransferSell,
                    cost: restaurantTransferCost,
                    sell: restaurantTransferSell,
                    zonePrivatePrice: restaurantZonePrice.private_price,
                    zoneSharedPrice: restaurantZonePrice.shared_price,
                    isStandalone: false,
                    sourceType: 'meal',
                    sourceId: mealId
                };
                
                // Check if transfer already exists - update it instead of adding new
                if (transferId) {
                    const existingTransferIndex = transferList.findIndex(t => t.id === transferId);
                    if (existingTransferIndex !== -1) {
                        // Update existing transfer
                        transferEntry.id = transferId;
                        transferList[existingTransferIndex] = transferEntry;
                        console.log('Updated existing transfer with ID:', transferId);
                    } else {
                        // Transfer ID exists but not found in list - add as new with same ID
                        transferEntry.id = transferId;
                        transferList.push(transferEntry);
                        console.log('Added transfer with existing ID:', transferId);
                    }
                    transferEntryId = transferId;
                } else {
                    // No existing transfer - create new one
                    transferEntryId = generateId('transfer');
                    transferEntry.id = transferEntryId;
                    transferList.push(transferEntry);
                    transferId = transferEntryId;
                    console.log('Created new transfer with ID:', transferEntryId);
                }
            } else if (!transferChecked && transferId) {
                // Transfer checkbox unchecked and there was an existing transfer - remove it
                console.log('Removing transfer with ID:', transferId);
                transferList = transferList.filter(t => t.id !== transferId);
                transferId = null;
                console.log('Transfer removed, updating tables');
                // Immediately update transfer table and recalculate totals to remove the price from footer
                updateTransferTable();
                recalculateTotals();
            } else {
                console.log('No transfer changes needed');
                transferId = null;
            }
            
            // Get restaurant ID from dropdown (restaurantSelect and restaurantName already declared above)
            const restaurantId = restaurantSelect ? restaurantSelect.value : '';
            
            // Get guide info from restaurant guide section
            const guideChecked = document.getElementById('restaurantGuideCheckbox')?.checked || false;
            const guideSelect = document.getElementById('restaurantGuideSelect');
            
            // Get adult and child quantities from modal inputs
            const restaurantGuideAdultQty = parseInt(document.getElementById('restaurantGuideAdultQty')?.value || '0') || 0;
            const restaurantGuideChildQty = parseInt(document.getElementById('restaurantGuideChildQty')?.value || '0') || 0;
            
            let guideId = null;
            let guideInfo = null;
            
            // oldMeal is already declared above at line 12028, reuse it
            
            if (guideChecked && guideSelect && guideSelect.value) {
                guideId = guideSelect.value;
                const guideOption = guideSelect.selectedOptions[0];
                const hoursSelect = document.getElementById('restaurantGuideHours');
                const hours = parseInt(hoursSelect?.value || '12') || 12;
                
                // Calculate price based on hours
                let price = 0;
                switch(hours) {
                    case 2:
                        price = parseFloat(guideOption?.getAttribute('data-two-hour-price') || '0') || 0;
                        break;
                    case 4:
                        price = parseFloat(guideOption?.getAttribute('data-four-hour-price') || '0') || 0;
                        break;
                    case 6:
                        price = parseFloat(guideOption?.getAttribute('data-six-hour-price') || '0') || 0;
                        break;
                    case 8:
                        price = parseFloat(guideOption?.getAttribute('data-eight-hour-price') || '0') || 0;
                        break;
                    case 10:
                        price = parseFloat(guideOption?.getAttribute('data-ten-hour-price') || '0') || 0;
                        break;
                    case 12:
                    default:
                        price = parseFloat(guideOption?.getAttribute('data-twelve-hour-price') || '0') || 0;
                        break;
                }
                
                guideInfo = {
                    guideId: guideId,
                    guideName: guideOption?.getAttribute('data-name') || guideOption?.text || '',
                    languages: guideOption?.getAttribute('data-languages') || ''
                };
                console.log('Guide selected:', guideInfo, 'Hours:', hours, 'Price:', price);
                
                // If guide changed or newly added, update guideList
                if (oldMeal.guideId !== guideId) {
                    // Remove old guide if exists
                    if (oldMeal.guideId) {
                        guideList = guideList.filter(g => String(g.id) !== String(oldMeal.guideId));
                    }
                    
                    // Add new guide entry
                    const guideEntryId = generateId('guide');
                    const guideEntry = {
                        id: guideEntryId,
                        dateTime: dateTime,
                        tourActivity: `${restaurantName} (Restaurant Guide)`,
                        language: guideInfo.languages || 'N/A',
                        guideName: guideInfo.guideName,
                        guideId: guideInfo.guideId,
                        hours: hours,
                        cost: price,
                        sell: price,
                        supplement: false,
                        isStandalone: false,
                        linkedTo: 'restaurant',
                        restaurantName: restaurantName,
                        adultsQty: restaurantGuideAdultQty,
                        childQty: restaurantGuideChildQty
                    };
                    guideList.push(guideEntry);
                    guideId = guideEntryId; // Update guideId to the entry ID
                } else {
                    // Update existing guide entry with new hours and price
                    const existingGuideIndex = guideList.findIndex(g => String(g.id) === String(oldMeal.guideId));
                    if (existingGuideIndex !== -1) {
                        guideList[existingGuideIndex].hours = hours;
                        guideList[existingGuideIndex].cost = price;
                        guideList[existingGuideIndex].sell = price;
                        guideList[existingGuideIndex].adultsQty = restaurantGuideAdultQty;
                        guideList[existingGuideIndex].childQty = restaurantGuideChildQty;
                    }
                }
            } else {
                // Guide unchecked, remove from guideList if exists
                if (oldMeal.guideId) {
                    guideList = guideList.filter(g => String(g.id) !== String(oldMeal.guideId));
                }
            }
            
            // Create meal data
            const mealData = {
                id: mealId, // Keep existing ID when editing (this is the meal list entry ID)
                destination: document.getElementById('mealDestination').value || 'Singapore',
                restaurantId: restaurantId,
                restaurantName: restaurantName,
                mealId: mealItemId, // This is the meal item ID from database
                mealName: mealName,
                mealType: mealType,
                dateTime: dateTime,
                mealCount: mealCount,
                adultsQty: adultsQty,
                adultCost: adultCost,
                adultSell: adultSell,
                childQty: childQty,
                childCost: childCost,
                childSell: childSell,
                infantQty: infantQty,
                infantCost: infantCost,
                infantSell: infantSell,
                transferId: transferId, // Will be null if transfer unchecked
                transferInfo: transferInfo, // Will be null if transfer unchecked
                guideId: guideId,
                guideInfo: guideInfo
            };
            
            console.log('Updated meal data:', mealData);
            
            // Update the meal
            mealList[window.editingMealIndex] = mealData;
            window.editingMealIndex = null;
            
            // Update header dates if needed
            recalculateHeaderDatesFromServices();
        } else {
            // Get restaurant info once (applies to all meals)
            const restaurantSelect = document.getElementById('mealRestaurant');
            const restaurantName = restaurantSelect && restaurantSelect.value 
                ? restaurantSelect.options[restaurantSelect.selectedIndex].getAttribute('data-name') 
                : 'Unknown Restaurant';
            const restaurantId = restaurantSelect ? restaurantSelect.value : '';
            
            // Get transfer info from restaurant transfer section (applies to all meals)
            const transferChecked = document.getElementById('restaurantTransferCheckbox')?.checked || false;
            const transferDestinationSelect = document.getElementById('restaurantTransferDestination');
            const transferDestination = transferDestinationSelect?.value || '';
            // Get destination name from data-name attribute (works with Select2)
            const transferDestinationOption = $('#restaurantTransferDestination').find(':selected');
            const transferDestinationName = transferDestinationOption.attr('data-name') || transferDestinationOption.text() || transferDestination;
            // Get vehicle type name from data attribute instead of value (which is vehicle_id)
            const vehicleTypeSelect = document.getElementById('restaurantTransferVehicleType');
            const vehicleId = vehicleTypeSelect?.value || '';
            const vehicleOption = vehicleTypeSelect?.selectedOptions[0];
            const vehicleType = vehicleOption?.getAttribute('data-type') || 'sedan';
            const vehicleName = vehicleOption?.text || '';
            const vehicleCapacity = parseInt(vehicleOption?.getAttribute('data-seating')) || 0;
            const transferWay = document.getElementById('restaurantTransferWay')?.value || 'one-way';
            const transferType = document.getElementById('restaurantTransferType')?.value || 'S';
            
            // Adding new meals - loop through selected rows and collect IDs first
            const mealIds = [];
            selectedRows.forEach(checkbox => {
                mealIds.push(generateId('meal'));
            });
            
            // Create ONE transfer entry if checkbox is checked (shared by all meals)
            let transferInfo = null;
            let transferId = null;
            let transferEntryId = null;
            
            if (transferChecked && transferDestination) {
                // First, calculate total adults and child from all selected meals
                let totalAdults = 0;
                let totalChild = 0;
                selectedRows.forEach(checkbox => {
                    const row = checkbox.closest('tr');
                    const adultsQty = parseInt(row.querySelector('.meal-adult-qty').value) || 0;
                    const childQty = parseInt(row.querySelector('.meal-child-qty').value) || 0;
                    totalAdults += adultsQty;
                    totalChild += childQty;
                });
                
                transferEntryId = generateId('transfer');
                
                // Get "Is PickUp?" checkbox state
                const isDestinationPickup = document.getElementById('restaurantTransferIsPickup')?.checked || false;
                
                transferInfo = {
                    destination: transferDestinationName,
                    vehicleType: vehicleType,
                    type: transferType,
                    way: transferWay,
                    isDestinationPickup: isDestinationPickup
                };
                
                // Fetch zone price for restaurant transfer (similar to hotel transfers)
                let restaurantZonePrice = { private_price: 0, shared_price: 0 };
                let restaurantTransferCost = 0;
                let restaurantTransferSell = 0;
                
                // Get restaurant ID and destination details for zone price calculation
                const actualRestaurantId = restaurantId;
                const actualDestinationId = transferDestination;
                const destinationType = transferDestinationOption.attr('data-type') || 'hotel';
                const dmcId = '{{ $dmc_id ?? "" }}';
                
                // Determine pickup and dropoff based on checkbox
                let pickupId, pickupType, dropoffId, dropoffType, pickupName, dropoffName;
                if (isDestinationPickup) {
                    // Destination is pickup, Restaurant is dropoff
                    pickupId = actualDestinationId;
                    pickupType = destinationType;
                    pickupName = transferDestinationName;
                    dropoffId = actualRestaurantId;
                    dropoffType = 'restaurant';
                    dropoffName = restaurantName;
                } else {
                    // Restaurant is pickup, Destination is dropoff (default behavior)
                    pickupId = actualRestaurantId;
                    pickupType = 'restaurant';
                    pickupName = restaurantName;
                    dropoffId = actualDestinationId;
                    dropoffType = destinationType;
                    dropoffName = transferDestinationName;
                }
                
                if (vehicleId && pickupId && dropoffId && dmcId) {
                    try {
                        restaurantZonePrice = await fetchZonePrice(
                            vehicleId,
                            pickupId,
                            pickupType,
                            dropoffId,
                            dropoffType,
                            dmcId
                        );
                        
                        // Calculate prices using zone price and total pax
                        const prices = calculateTransferPrice(restaurantZonePrice, transferType, transferWay, totalAdults, totalChild);
                        restaurantTransferCost = prices.cost || 0;
                        restaurantTransferSell = prices.sell || 0;
                    } catch (error) {
                        console.error('Error fetching zone price for restaurant transfer:', error);
                        // Fallback: keep price as 0
                    }
                }
                
                // Add to transfer list - use first meal ID as source
                const transferEntry = {
                    id: transferEntryId,
                    dateTime: dateTime,
                    service: `${pickupName} / ${dropoffName}`,
                    restaurantName: restaurantName, // Store restaurant name for entrypickup
                    transportMode: 'local',
                    type: transferType,
                    vehicleId: vehicleId,
                    vehicleName: vehicleName,
                    vehicleType: vehicleType,
                    capacity: vehicleCapacity,
                    way: transferWay,
                    destination: transferDestinationName,
                    destinationId: transferDestination, // Store destination ID for easier lookup when editing
                    pickup: pickupName,
                    dropoff: dropoffName,
                    isDestinationPickup: isDestinationPickup,
                    adults: totalAdults,
                    adultsQty: totalAdults,
                    child: totalChild,
                    childQty: totalChild,
                    adultCost: restaurantTransferCost,
                    adultSell: restaurantTransferSell,
                    childCost: restaurantTransferCost,
                    childSell: restaurantTransferSell,
                    cost: restaurantTransferCost,
                    sell: restaurantTransferSell,
                    zonePrivatePrice: restaurantZonePrice.private_price,
                    zoneSharedPrice: restaurantZonePrice.shared_price,
                    isStandalone: false,
                    sourceType: 'meal',
                    sourceId: mealIds[0] // Link to first meal
                };
                
                transferList.push(transferEntry);
                transferId = transferEntryId;
            }
            
            // Get guide info from restaurant guide section (shared by all meals)
            const guideChecked = document.getElementById('restaurantGuideCheckbox')?.checked || false;
            const guideSelect = document.getElementById('restaurantGuideSelect');
            
            // Get adult and child quantities from modal inputs
            const restaurantGuideAdultQty = parseInt(document.getElementById('restaurantGuideAdultQty')?.value || '0') || 0;
            const restaurantGuideChildQty = parseInt(document.getElementById('restaurantGuideChildQty')?.value || '0') || 0;
            
            let guideId = null;
            let guideInfo = null;
            let guideEntryId = null;
            
            if (guideChecked && guideSelect && guideSelect.value) {
                guideId = guideSelect.value;
                const guideOption = guideSelect.selectedOptions[0];
                const hoursSelect = document.getElementById('restaurantGuideHours');
                const hours = parseInt(hoursSelect?.value || '12') || 12;
                
                // Calculate price based on hours
                let price = 0;
                switch(hours) {
                    case 2:
                        price = parseFloat(guideOption?.getAttribute('data-two-hour-price') || '0') || 0;
                        break;
                    case 4:
                        price = parseFloat(guideOption?.getAttribute('data-four-hour-price') || '0') || 0;
                        break;
                    case 6:
                        price = parseFloat(guideOption?.getAttribute('data-six-hour-price') || '0') || 0;
                        break;
                    case 8:
                        price = parseFloat(guideOption?.getAttribute('data-eight-hour-price') || '0') || 0;
                        break;
                    case 10:
                        price = parseFloat(guideOption?.getAttribute('data-ten-hour-price') || '0') || 0;
                        break;
                    case 12:
                    default:
                        price = parseFloat(guideOption?.getAttribute('data-twelve-hour-price') || '0') || 0;
                        break;
                }
                
                guideInfo = {
                    guideId: guideId,
                    guideName: guideOption?.getAttribute('data-name') || guideOption?.text || '',
                    languages: guideOption?.getAttribute('data-languages') || ''
                };
                console.log('Guide selected for meals:', guideInfo, 'Hours:', hours, 'Price:', price);
                
                // Create guide entry for guide table (ONE guide entry for all meals at this restaurant)
                guideEntryId = generateId('guide');
                const guideEntry = {
                    id: guideEntryId,
                    dateTime: dateTime,
                    tourActivity: `${restaurantName} (Restaurant Guide)`,
                    language: guideInfo.languages || 'N/A',
                    guideName: guideInfo.guideName,
                    guideId: guideInfo.guideId,
                    hours: hours,
                    cost: price,
                    sell: price,
                    supplement: false,
                    isStandalone: false, // Linked to restaurant
                    linkedTo: 'restaurant',
                    restaurantName: restaurantName,
                    adultsQty: restaurantGuideAdultQty,
                    childQty: restaurantGuideChildQty
                };
                
                guideList.push(guideEntry);
                console.log('Added guide to guideList:', guideEntry);
            }
            
            // Adding new meals - loop through selected rows
            selectedRows.forEach((checkbox, index) => {
                const mealId = checkbox.getAttribute('data-meal-id');
                const row = checkbox.closest('tr');
                const mealName = row.getAttribute('data-meal-name');
                const mealType = row.getAttribute('data-meal-type') || mealName;
                
                // Get values from the row
                const mealCount = parseInt(row.querySelector('.meal-count').value) || 0;
                const adultsQty = parseInt(row.querySelector('.meal-adult-qty').value) || 0;
                const adultCostValue = row.querySelector('.meal-adult-cost')?.value || 'SGD 0.00';
                const adultSellValue = row.querySelector('.meal-adult-sell')?.value || 'SGD 0.00';
                const childQty = parseInt(row.querySelector('.meal-child-qty').value) || 0;
                const childCostValue = row.querySelector('.meal-child-cost')?.value || 'SGD 0.00';
                const childSellValue = row.querySelector('.meal-child-sell')?.value || 'SGD 0.00';
                const infantQty = parseInt(row.querySelector('.meal-infant-qty').value) || 0;
                const infantCostValue = row.querySelector('.meal-infant-cost')?.value || 'SGD 0.00';
                const infantSellValue = row.querySelector('.meal-infant-sell')?.value || 'SGD 0.00';
                
                // Parse cost and sell prices separately
                const adultCost = parseFloat(adultCostValue.replace(/[^0-9.]/g, '')) || 0;
                const adultSell = parseFloat(adultSellValue.replace(/[^0-9.]/g, '')) || 0;
                const childCost = parseFloat(childCostValue.replace(/[^0-9.]/g, '')) || 0;
                const childSell = parseFloat(childSellValue.replace(/[^0-9.]/g, '')) || 0;
                const infantCost = parseFloat(infantCostValue.replace(/[^0-9.]/g, '')) || 0;
                const infantSell = parseFloat(infantSellValue.replace(/[^0-9.]/g, '')) || 0;
                
                // Create meal data (use shared transfer ID and guide for all meals, and pre-generated ID)
                const mealData = {
                    id: mealIds[index],
                    destination: document.getElementById('mealDestination').value || 'Singapore',
                    restaurantId: restaurantId,
                    restaurantName: restaurantName,
                    mealId: mealId,
                    mealName: mealName,
                    mealType: mealType,
                    dateTime: dateTime,
                    mealCount: mealCount,
                    adultsQty: adultsQty,
                    adultCost: adultCost,
                    adultSell: adultSell,
                    childQty: childQty,
                    childCost: childCost,
                    childSell: childSell,
                    infantQty: infantQty,
                    infantCost: infantCost,
                    infantSell: infantSell,
                    transferId: transferId, // Shared transfer ID
                    transferInfo: transferInfo, // Shared transfer info
                    guideId: guideId, // Shared guide ID
                    guideInfo: guideInfo // Shared guide info
                };
                
                mealList.push(mealData);
                
                // Update header dates if needed
                updateHeaderDatesIfNeeded(dateTime);
            });
        }
        
        // Update tables
        updateMealTable();
        updateGuideTable();
        updateTransferTable();
        recalculateTotals();
        
        // Close modal
        const mealModal = bootstrap.Modal.getInstance(document.getElementById('mealModal'));
        mealModal.hide();
        
        // Reset checkboxes
        document.getElementById('selectAllMeals').checked = false;
        document.querySelectorAll('.meal-checkbox').forEach(cb => cb.checked = false);
    }
    
    // Add another meal (keep modal open)
    async function addAnotherMeal() {
        const selectedRows = document.querySelectorAll('.meal-checkbox:checked');
        
        if (selectedRows.length === 0) {
            alert('Please select at least one meal');
            return;
        }
        
        // Save current selections without closing - wait for it to complete
        await saveAndCloseMeals();
        
        // Reopen the modal after save completes
        const mealModal = new bootstrap.Modal(document.getElementById('mealModal'));
        mealModal.show();
    }
    
    // Save meal
    function saveMeal() {
        const destination = document.getElementById('mealDestination').value;
        const restaurantSelect = document.getElementById('mealRestaurant');
        const restaurantId = restaurantSelect.value;
        const restaurantName = restaurantSelect.options[restaurantSelect.selectedIndex]?.text || '';
        const dateTime = document.getElementById('mealDateTime').value;
        const adultsQty = parseInt(document.getElementById('mealAdultsQty').value);
        const adultCost = parseFloat(document.getElementById('mealAdultCost').value);
        const adultSell = parseFloat(document.getElementById('mealAdultSell').value);
        const childQty = parseInt(document.getElementById('mealChildQty').value);
        const childCost = parseFloat(document.getElementById('mealChildCost').value);
        const childSell = parseFloat(document.getElementById('mealChildSell').value);
        
        if (!restaurantId || !dateTime) {
            alert('Please select restaurant and date/time');
            return;
        }
        
        const isEditing = window.editingMealIndex !== undefined && window.editingMealIndex !== null;
        
        // Get transfer info
        const transferRequired = document.getElementById('mealTransferRequired').value === 'yes';
        let transferInfo = null;
        let transferId = null;
        
        if (transferRequired) {
            const transferType = document.getElementById('mealTransferType').value;
            const transferWay = document.getElementById('mealTransferWay').value;
            const vehicleType = document.getElementById('mealVehicleType').value;
            const transferCost = parseFloat(document.getElementById('mealTransferCost').value);
            const transferSell = parseFloat(document.getElementById('mealTransferSell').value);
            
            transferId = generateId('transfer');
            transferInfo = {
                id: transferId,
                type: transferType,
                way: transferWay,
                vehicleType: vehicleType,
                cost: transferCost,
                sell: transferSell,
                destination: restaurantName,
                dateTime: dateTime,
                adults: adultsQty,
                adultsQty: adultsQty,
                child: childQty,
                childQty: childQty,
                taxIncluded: true,
                isStandalone: false
            };
            
            // Add to transfer list
            transferList.push(transferInfo);
        }
        
    const mealData = {
        id: generateId('meal'),
            destination: destination,
            restaurantId: restaurantId,
            restaurantName: restaurantName,
            dateTime: dateTime,
            adultsQty: adultsQty,
            adultCost: adultCost,
            adultSell: adultSell,
            childQty: childQty,
            childCost: childCost,
            childSell: childSell,
            transferId: transferId,
            transferInfo: transferInfo
        };
        
        // Check if editing
        if (isEditing) {
            // Remove old transfer if exists
            const oldMeal = mealList[window.editingMealIndex];
            if (oldMeal.transferId) {
                transferList = transferList.filter(t => t.id !== oldMeal.transferId);
            }
            
            mealList[window.editingMealIndex] = mealData;
            window.editingMealIndex = null;
        } else {
            mealList.push(mealData);
        }
        
        // Update header dates
        if (isEditing) {
            // When editing, recalculate from all services to handle date changes properly
            recalculateHeaderDatesFromServices();
        } else {
            // When adding new, just expand if needed
            expandHeaderDatesIfNeeded(dateTime, true);
        }
        
        updateMealTable();
        updateTransferTable();
        recalculateTotals();
        
        // Close modal
        const mealModal = bootstrap.Modal.getInstance(document.getElementById('mealModal'));
        mealModal.hide();
    }
    
    // Update meal table
    function updateMealTable() {
        const tbody = document.getElementById('mealTableBody');
        const table = document.getElementById('mealTable');
        const emptyMessage = document.getElementById('emptyMealMessage');
        
        if (mealList.length === 0) {
            table.style.display = 'none';
            emptyMessage.style.display = 'block';
            return;
        }
        
        table.style.display = 'table';
        emptyMessage.style.display = 'none';
        
        tbody.innerHTML = mealList.map((meal, index) => {
            // Ensure dateTime has time component, if not add default time based on meal type
            let dateTimeValue = meal.dateTime || '';
            if (dateTimeValue && !dateTimeValue.includes('T')) {
                // Default times: Breakfast 08:00, Lunch 12:00, Dinner 19:00
                const mealType = (meal.mealType || '').toLowerCase();
                let defaultTime = '12:00'; // Default to lunch time
                if (mealType.includes('breakfast')) defaultTime = '08:00';
                else if (mealType.includes('dinner')) defaultTime = '19:00';
                dateTimeValue = dateTimeValue + 'T' + defaultTime;
            }
            
            return `
            <tr>
                <td><input type="checkbox" class="meal-checkbox" value="${meal.id}"></td>
                <td><input type="datetime-local" value="${dateTimeValue}" onchange="updateMealField(${index}, 'dateTime', this.value)" style="width: 130px; font-size: 11px; padding: 2px 4px;"></td>
                <td>
                    <a href="javascript:void(0)" onclick="editMeal(${index})" style="color: #0d6efd; text-decoration: underline; cursor: pointer;">
                        ${meal.restaurantName || 'Restaurant'} - ${meal.mealType || meal.mealName || 'Meal'}
                    </a>
                </td>
                <td><input type="number" value="${meal.adultsQty}" onchange="updateMealField(${index}, 'adultsQty', this.value)"></td>
                <td><input type="text" value="${meal.adultCost}" readonly style="background-color: #f5f5f5;"></td>
                <td><input type="number" value="${meal.adultSell}" onchange="updateMealField(${index}, 'adultSell', this.value)" step="1"></td>
                <td><input type="number" value="${meal.childQty}" onchange="updateMealField(${index}, 'childQty', this.value)"></td>
                <td><input type="text" value="${meal.childCost}" readonly style="background-color: #f5f5f5;"></td>
                <td><input type="number" value="${meal.childSell}" onchange="updateMealField(${index}, 'childSell', this.value)" step="1"></td>
                <td style="text-align: center;"><input type="checkbox" ${meal.supplement ? 'checked' : ''} onchange="updateMealSupplement(${index}, this.checked)"></td>
            </tr>
        `;
        }).join('');
    }
    
    // Ensure a meal row exists in the popup table for editing (for dynamically loaded meals)
    function ensureMealRowForEdit(meal) {
        const tbody = document.getElementById('mealsTableBody');
        if (!tbody) return null;
        
        const mealId = meal.restaurantId || meal.id || generateId('meal');
        const mealName = meal.restaurantName || 'Restaurant';
        const mealType = meal.mealType || 'custom';
        
        const existing = tbody.querySelector(`tr.meal-row[data-meal-id="${mealId}"]`);
        if (existing) return existing;
        
        // Get transfer info - check transferList first if transferId exists
        let transferInfo = meal.transferInfo || {};
        const hasTransfer = !!meal.transferInfo || !!meal.transferId;
        
        if (meal.transferId && !meal.transferInfo) {
            const linkedTransfer = transferList.find(t => t.id === meal.transferId);
            if (linkedTransfer) {
                transferInfo = {
                    destination: linkedTransfer.destination,
                    vehicleType: linkedTransfer.vehicleType || 'sedan',
                    type: linkedTransfer.mode === 'Private' ? 'private' : 'sic',
                    way: linkedTransfer.way === 'Both Way' ? 'both-way' : 'one-way',
                    isDestinationPickup: linkedTransfer.isDestinationPickup || false
                };
            }
        }
        
        const row = document.createElement('tr');
        row.className = 'meal-row';
        row.setAttribute('data-meal-id', mealId);
        row.setAttribute('data-meal-name', mealName);
        row.setAttribute('data-meal-type', mealType);
        row.innerHTML = `
            <td style="padding: 2px 8px; text-align: center;">
                <input type="checkbox" class="meal-checkbox" data-meal-id="${mealId}">
            </td>
            <td style="padding: 2px 8px;">
                ${mealName} <small class="text-muted">(${mealType})</small>
            </td>
            <td style="padding: 2px 8px;">
                <input type="number" class="form-control form-control-sm meal-count" data-meal-id="${mealId}" value="${meal.mealCount ?? 0}" min="0" style="font-size: 10px; padding: 2px 4px; text-align: center;">
            </td>
            <td style="padding: 2px 8px;">
                <input type="number" class="form-control form-control-sm meal-adult-qty" data-meal-id="${mealId}" value="${meal.adultsQty ?? 0}" min="0" style="font-size: 10px; padding: 2px 4px; text-align: center;">
            </td>
            <td style="padding: 2px 8px;">
                <input type="text" class="form-control form-control-sm meal-adult-charge" data-meal-id="${mealId}" value="${meal.adultCost ?? 0}" readonly style="font-size: 10px; padding: 2px 4px; background-color: #f5f5f5;">
            </td>
            <td style="padding: 2px 8px;">
                <input type="number" class="form-control form-control-sm meal-child-qty" data-meal-id="${mealId}" value="${meal.childQty ?? 0}" min="0" style="font-size: 10px; padding: 2px 4px; text-align: center;">
            </td>
            <td style="padding: 2px 8px;">
                <input type="text" class="form-control form-control-sm meal-child-charge" data-meal-id="${mealId}" value="${meal.childCost ?? 0}" readonly style="font-size: 10px; padding: 2px 4px; background-color: #f5f5f5;">
            </td>
            <td style="padding: 2px 8px;">
                <input type="number" class="form-control form-control-sm meal-infant-qty" data-meal-id="${mealId}" value="${meal.infantQty ?? 0}" min="0" style="font-size: 10px; padding: 2px 4px; text-align: center;">
            </td>
            <td style="padding: 2px 8px;">
                <input type="text" class="form-control form-control-sm meal-infant-charge" data-meal-id="${mealId}" value="${meal.infantCost ?? 0}" readonly style="font-size: 10px; padding: 2px 4px; background-color: #f5f5f5;">
            </td>
            <td style="padding: 2px 8px; text-align: center;">
                <input type="checkbox" class="form-check-input meal-transfer-checkbox" data-meal-id="${mealId}" ${hasTransfer ? 'checked' : ''}>
            </td>
            <td style="padding: 2px 8px;">
                <select class="form-select form-select-sm meal-transfer-destination" data-meal-id="${mealId}" style="font-size: 10px; padding: 2px 4px;">
                    <option value="">Select Destination</option>
                    ${getMealDestinationOptionsHTML(transferInfo.destination)}
                </select>
            </td>
            <td style="padding: 2px 8px;">
                <select class="form-select form-select-sm meal-vehicle-type" data-meal-id="${mealId}" style="font-size: 10px; padding: 2px 4px;">
                    <option value="sedan" ${transferInfo.vehicleType === 'sedan' ? 'selected' : ''}>Sedan</option>
                    <option value="combi" ${transferInfo.vehicleType === 'combi' ? 'selected' : ''}>Combi</option>
                    <option value="van" ${transferInfo.vehicleType === 'van' ? 'selected' : ''}>Van</option>
                    <option value="bus" ${transferInfo.vehicleType === 'bus' ? 'selected' : ''}>Bus</option>
                </select>
            </td>
            <td style="padding: 2px 8px;">
                <select class="form-select form-select-sm meal-direction" data-meal-id="${mealId}" style="font-size: 10px; padding: 2px 4px;">
                    <option value="1way" ${transferInfo.way === '1way' || transferInfo.way === 'one-way' ? 'selected' : ''}>One Way</option>
                    <option value="2way" ${transferInfo.way === 'both-way' || transferInfo.way === '2way' ? 'selected' : ''}>Two Way</option>
                </select>
            </td>
            <td style="padding: 2px 8px;">
                <select class="form-select form-select-sm meal-transfer-type" data-meal-id="${mealId}" style="font-size: 10px; padding: 2px 4px;">
                    <option value="S" ${transferInfo.type === 'S' || transferInfo.type === 'sic' ? 'selected' : ''}>Shared</option>
                    <option value="P" ${transferInfo.type === 'P' || transferInfo.type === 'private' ? 'selected' : ''}>Private</option>
                </select>
            </td>
        `;
        
        // Prepend so it's visible immediately
        tbody.prepend(row);
        return row;
    }
    
    // Edit meal
    async function editMeal(index) {
        const meal = mealList[index];
        if (!meal) return;
        
        console.log('=== EDITING MEAL ===');
        console.log('Index:', index);
        console.log('Full meal object:', JSON.parse(JSON.stringify(meal)));
        console.log('Restaurant:', meal.restaurantName, 'ID:', meal.restaurantId);
        console.log('Meal Name:', meal.mealName, 'Type:', meal.mealType);
        console.log('Destination:', meal.destination);
        console.log('Transfer ID:', meal.transferId);
        console.log('Transfer Info:', meal.transferInfo);
        console.log('Current transferList:', JSON.parse(JSON.stringify(transferList)));
        
        if (meal.transferId) {
            const linkedTransfer = transferList.find(t => t.id === meal.transferId);
            console.log('Linked transfer found:', linkedTransfer);
        }
        
        window.editingMealIndex = index;
        
        // Set date and time - for datetime-local input, we need full datetime format (YYYY-MM-DDTHH:mm)
        let dateTimeValue = meal.dateTime || '';
        // If the datetime doesn't have a time component, add default time 09:00
        if (dateTimeValue && !dateTimeValue.includes('T')) {
            dateTimeValue = dateTimeValue + 'T09:00';
        }
        document.getElementById('mealDateTime').value = dateTimeValue;
        
        // Set destination
        const destinationSelect = document.getElementById('mealDestination');
        if (destinationSelect && meal.destination) {
            destinationSelect.value = meal.destination;
        }
        
        // Load restaurants for this destination
        loadRestaurantsByDestination();
        
        // Wait a moment for restaurants to load, then select the restaurant
        await new Promise(resolve => setTimeout(resolve, 100));
        
        const restaurantSelect = document.getElementById('mealRestaurant');
        if (restaurantSelect && meal.restaurantId) {
            restaurantSelect.value = meal.restaurantId;
            
            // Load meals from this restaurant and wait for it to complete
            await updateMealsFromRestaurant();
            
            // Now populate the form - meals are loaded
            populateMealFormForEdit(meal);
            
            // Populate restaurant transfer section if transfer exists
            if (meal.transferId || meal.transferInfo) {
                console.log('=== Populating Transfer Section for Edit ===');
                console.log('Meal data:', meal);
                
                const restaurantTransferCheckbox = document.getElementById('restaurantTransferCheckbox');
                if (restaurantTransferCheckbox) {
                    restaurantTransferCheckbox.checked = true;
                    toggleRestaurantTransferFields(); // Show the fields
                }
                
                // Get transfer info - prioritize meal.transferInfo, then lookup from transferList
                let tInfo = null;
                
                if (meal.transferInfo) {
                    // Use the transfer info stored with the meal
                    tInfo = meal.transferInfo;
                    console.log('Using meal.transferInfo:', tInfo);
                } else if (meal.transferId) {
                    // Lookup from transferList
                    const linkedTransfer = transferList.find(t => t.id === meal.transferId);
                    console.log('Looking up transfer with ID:', meal.transferId, 'Found:', linkedTransfer);
                    if (linkedTransfer) {
                        tInfo = {
                            destination: linkedTransfer.destination,
                            destinationId: linkedTransfer.destinationId || null, // Store destination ID if available
                            vehicleId: linkedTransfer.vehicleId || '',
                            vehicleType: linkedTransfer.vehicleType || 'sedan',
                            type: linkedTransfer.type || 'S', // Use type directly (S or P)
                            way: linkedTransfer.way || 'one-way', // Use way directly (one-way or both-way)
                            isDestinationPickup: linkedTransfer.isDestinationPickup || false
                        };
                    }
                }
                
                if (tInfo) {
                    console.log('Final transfer info to populate:', tInfo);
                    
                    // Wait a bit for Select2 to be ready, then populate transfer fields
                    await new Promise(resolve => setTimeout(resolve, 200));
                    
                    const destSelect = document.getElementById('restaurantTransferDestination');
                    if (destSelect && tInfo.destination) {
                        // Try to find option by destination ID first, then by name
                        let destinationValue = null;
                        
                        if (tInfo.destinationId) {
                            // Try to find by value (destination ID)
                            destinationValue = tInfo.destinationId;
                        } else {
                            // Find option by data-name attribute matching destination name
                            const options = Array.from(destSelect.options);
                            const matchingOption = options.find(opt => {
                                const dataName = opt.getAttribute('data-name');
                                return dataName && dataName === tInfo.destination;
                            });
                            
                            if (matchingOption) {
                                destinationValue = matchingOption.value;
                            } else {
                                // Fallback: try to match by text
                                const textMatch = options.find(opt => opt.text === tInfo.destination);
                                if (textMatch) {
                                    destinationValue = textMatch.value;
                                }
                            }
                        }
                        
                        if (destinationValue) {
                            destSelect.value = destinationValue;
                            // Trigger change event for Select2 if it's being used
                            if (window.jQuery && jQuery(destSelect).hasClass('select2-hidden-accessible')) {
                                jQuery(destSelect).trigger('change');
                            }
                            console.log('Set destination to:', destinationValue, 'for destination name:', tInfo.destination);
                        } else {
                            console.warn('Could not find destination option for:', tInfo.destination);
                        }
                    }
                    
                    const vehicleSelect = document.getElementById('restaurantTransferVehicleType');
                    if (vehicleSelect && tInfo.vehicleId) {
                        vehicleSelect.value = tInfo.vehicleId;
                        // Trigger change event for Select2 if it's being used
                        if (window.jQuery && jQuery(vehicleSelect).hasClass('select2-hidden-accessible')) {
                            jQuery(vehicleSelect).trigger('change');
                        }
                        console.log('Set vehicle to:', tInfo.vehicleId);
                    }
                    
                    // Set "Is PickUp?" checkbox state
                    const isPickupCheckbox = document.getElementById('restaurantTransferIsPickup');
                    if (isPickupCheckbox) {
                        isPickupCheckbox.checked = tInfo.isDestinationPickup || false;
                        console.log('Set isDestinationPickup to:', tInfo.isDestinationPickup || false);
                    }
                    
                    const waySelect = document.getElementById('restaurantTransferWay');
                    if (waySelect && tInfo.way) {
                        // Normalize way value
                        let wayValue = tInfo.way;
                        if (wayValue === 'Both Way' || wayValue === 'both' || wayValue === '2way') {
                            wayValue = 'both-way';
                        } else if (wayValue === 'One Way' || wayValue === 'one' || wayValue === '1way') {
                            wayValue = 'one-way';
                        }
                        waySelect.value = wayValue;
                        console.log('Set way to:', wayValue);
                    }
                    
                    const typeSelect = document.getElementById('restaurantTransferType');
                    if (typeSelect && tInfo.type) {
                        // Normalize type value
                        let typeValue = tInfo.type;
                        if (typeValue === 'P' || typeValue === 'private' || typeValue === 'Private') {
                            typeValue = 'P';
                        } else if (typeValue === 'S' || typeValue === 'sic' || typeValue === 'Shared') {
                            typeValue = 'S';
                        }
                        typeSelect.value = typeValue;
                        console.log('Set type to:', typeValue);
                    }
                } else {
                    console.warn('No transfer info found for meal');
                }
            } else {
                console.log('No transfer data for this meal');
                // Clear transfer form fields if no transfer data exists
                resetRestaurantTransferFields();
            }
            
            // Populate restaurant guide section if guide exists
            if (meal.guideId || meal.guideInfo) {
                console.log('=== Populating Guide Section for Edit ===');
                console.log('Guide data:', meal.guideInfo);
                
                const restaurantGuideCheckbox = document.getElementById('restaurantGuideCheckbox');
                if (restaurantGuideCheckbox) {
                    restaurantGuideCheckbox.checked = true;
                    toggleRestaurantGuideFields(); // Show the fields
                }
                
                await new Promise(resolve => setTimeout(resolve, 100));
                
                const guideSelect = document.getElementById('restaurantGuideSelect');
                const hoursSelect = document.getElementById('restaurantGuideHours');
                if (guideSelect && meal.guideId) {
                    // Find guide entry in guideList to get actual guide ID and hours
                    const guideEntry = guideList.find(g => String(g.id) === String(meal.guideId));
                    if (guideEntry) {
                        guideSelect.value = guideEntry.guideId; // Use actual guide ID, not entry ID
                        if (hoursSelect && guideEntry.hours) {
                            hoursSelect.value = guideEntry.hours;
                        }
                        updateRestaurantGuidePricing(); // Update pricing based on hours
                        console.log('Set guide to:', guideEntry.guideId, 'Hours:', guideEntry.hours);
                    } else {
                        // Fallback: try using meal.guideId directly (might be actual guide ID)
                        guideSelect.value = meal.guideId;
                        console.log('Set guide to (fallback):', meal.guideId);
                    }
                }
            } else {
                console.log('No guide data for this meal');
            }
        } else {
            // If no restaurant ID, just try to populate what we can
            populateMealFormForEdit(meal);
        }
        
        document.getElementById('mealModalTitleText').textContent = 'Edit Meal / Restaurant';
        const saveMealBtn = document.getElementById('saveMealBtnText');
        if (saveMealBtn) saveMealBtn.textContent = 'Update Meal';
        
        const mealModal = new bootstrap.Modal(document.getElementById('mealModal'));
        mealModal.show();
    }
    
    // Helper function to populate meal form fields for editing
    function populateMealFormForEdit(meal) {
        // Find matching meal row (by mealId or meal name)
        const rows = Array.from(document.querySelectorAll('.meal-row'));
        const targetRow = rows.find(r => {
            const rowMealId = r.getAttribute('data-meal-id');
            const rowName = r.getAttribute('data-meal-name');
            return (meal.mealId && String(meal.mealId) === rowMealId) || 
                   (meal.mealName && meal.mealName === rowName);
        });
        
        // If no matching row exists, create one dynamically
        let rowToUse = targetRow;
        if (!rowToUse) {
            rowToUse = ensureMealRowForEdit(meal);
        }
        
        // Reset all checkboxes first
        document.querySelectorAll('.meal-checkbox').forEach(cb => cb.checked = false);
        
        if (rowToUse) {
            const mealId = rowToUse.getAttribute('data-meal-id');
            
            // Check the row
            const checkbox = rowToUse.querySelector(`.meal-checkbox[data-meal-id="${mealId}"]`);
            if (checkbox) checkbox.checked = true;
            
            // Fill editable fields on the row
            const setVal = (selector, value) => {
                const el = rowToUse.querySelector(`${selector}[data-meal-id="${mealId}"]`);
                if (el) el.value = value ?? el.value;
            };
            
            setVal('.meal-count', meal.mealCount);
            setVal('.meal-adult-qty', meal.adultsQty);
            setVal('.meal-adult-charge', 'SGD ' + (meal.adultCost || 0));
            setVal('.meal-child-qty', meal.childQty);
            setVal('.meal-child-charge', 'SGD ' + (meal.childCost || 0));
            setVal('.meal-infant-qty', meal.infantQty);
            setVal('.meal-infant-charge', 'SGD ' + (meal.infantCost || 0));
            
            // Transfer fields
            const transferCheckbox = rowToUse.querySelector(`.meal-transfer-checkbox[data-meal-id="${mealId}"]`);
            if (transferCheckbox) {
                const hasTransfer = !!meal.transferInfo || !!meal.transferId;
                console.log('Has transfer:', hasTransfer, 'transferInfo:', meal.transferInfo, 'transferId:', meal.transferId);
                transferCheckbox.checked = hasTransfer;
                if (hasTransfer) {
                    // Try to get transfer info from transferList if transferId exists
                    let tInfo = meal.transferInfo || {};
                    if (meal.transferId) {
                        const linkedTransfer = transferList.find(t => t.id === meal.transferId);
                        console.log('Looking for transfer with id:', meal.transferId, 'Found:', linkedTransfer);
                        if (linkedTransfer) {
                            tInfo = {
                                destination: linkedTransfer.destination,
                                vehicleId: linkedTransfer.vehicleId || '',
                                vehicleType: linkedTransfer.vehicleType || 'sedan',
                                type: linkedTransfer.mode === 'Private' ? 'private' : 'sic',
                                way: linkedTransfer.way === 'Both Way' ? 'both-way' : 'one-way',
                                isDestinationPickup: linkedTransfer.isDestinationPickup || false
                            };
                        }
                    }
                    console.log('Setting transfer values:', tInfo);
                    setVal('.meal-transfer-destination', tInfo.destination);
                    setVal('.meal-vehicle-type', tInfo.vehicleId || tInfo.vehicleType || '');
                    setVal('.meal-transfer-type', tInfo.type || 'S');
                    const direction = tInfo.way === 'both-way' || tInfo.way === 'Both Way' || tInfo.way === '2way' ? '2way' : '1way';
                    setVal('.meal-direction', direction);
                }
            }
            
            // Optional and Supplement checkboxes
            const optionalCheckbox = rowToUse.querySelector(`.meal-optional-checkbox[data-meal-id="${mealId}"]`);
            if (optionalCheckbox && meal.optional) {
                optionalCheckbox.checked = meal.optional;
            }
            
            const supplementCheckbox = rowToUse.querySelector(`.meal-supplement-checkbox[data-meal-id="${mealId}"]`);
            if (supplementCheckbox && meal.supplement) {
                supplementCheckbox.checked = meal.supplement;
            }
            
            // Scroll the row into view
            rowToUse.scrollIntoView({ behavior: 'smooth', block: 'center' });
        } else {
            console.warn('populateMealFormForEdit: no matching meal row found for', meal.mealName || meal.mealId);
        }
    }
    
    // Update meal field
    function updateMealField(index, field, value) {
        if (mealList[index]) {
            const meal = mealList[index];
            meal[field] = value;
            
            // If supplement is changed, do NOT sync with linked services
            
            // If dateTime is changed, sync with linked transfer and expand header dates
            if (field === 'dateTime' && value) {
                if (meal.transferId) {
                    const transferIndex = transferList.findIndex(t => t.id === meal.transferId);
                    if (transferIndex !== -1) {
                        transferList[transferIndex].dateTime = value;
                        updateTransferTable();
                    }
                }
                
                // Expand header dates
                expandHeaderDatesIfNeeded(value, false);
            }
        }
    }
    
    // Update meal supplement - do NOT sync with linked services
    function updateMealSupplement(index, checked) {
        if (mealList[index]) {
            const meal = mealList[index];
            meal.supplement = checked;
            
            // Recalculate totals after supplement change
            recalculateTotals();
        }
    }
    
    // Toggle select all meals (main table)
    function toggleSelectAllMealsMain() {
        const selectAll = document.getElementById('selectAllMealsMain');
        const checkboxes = document.querySelectorAll('.meal-checkbox');
        checkboxes.forEach(cb => cb.checked = selectAll.checked);
    }
    
    // Remove selected meals
    function removeSelectedMeals() {
        const checkboxes = document.querySelectorAll('.meal-checkbox:checked');
        if (checkboxes.length === 0) {
            alert('Please select meals to remove');
            return;
        }
        
        if (!confirm(`Remove ${checkboxes.length} selected meal(s)?`)) {
            return;
        }
        
        const idsToRemove = Array.from(checkboxes).map(cb => cb.value);
        
        // Also remove associated transfers and guides
        mealList.forEach(meal => {
            if (idsToRemove.includes(String(meal.id))) {
                if (meal.transferId) {
                    transferList = transferList.filter(t => String(t.id) !== String(meal.transferId));
                }
                if (meal.guideId) {
                    guideList = guideList.filter(g => String(g.id) !== String(meal.guideId));
                }
            }
        });
        
        mealList = mealList.filter(meal => !idsToRemove.includes(String(meal.id)));
        
        updateMealTable();
        updateTransferTable();
        updateGuideTable();
        recalculateHeaderDatesFromServices();
        recalculateTotals();
    }

    // ==================== TRANSFER FUNCTIONS ====================
    
    // Update transfer table - displays all transfers from tours and meals
    function updateTransferTable() {
        const tbody = document.getElementById('transferTableBody');
        const table = document.getElementById('transferTable');
        const emptyMessage = document.getElementById('emptyTransferMessage');
        
        if (transferList.length === 0) {
            table.style.display = 'none';
            emptyMessage.style.display = 'block';
            return;
        }
        
        table.style.display = 'table';
        emptyMessage.style.display = 'none';
        
        // Helper function to get transport mode icon
        const getModeIcon = (mode) => {
            const icons = {
                'local': '<i class="ri-car-line" style="font-size: 16px;" title="Local Transfer"></i>',
                'flight': '<i class="ri-flight-takeoff-line" style="font-size: 16px;" title="Flight"></i>',
                'cruise': '<i class="ri-ship-line" style="font-size: 16px;" title="Cruise"></i>',
                'train': '<i class="ri-train-line" style="font-size: 16px;" title="Train"></i>',
                'bus': '<i class="ri-bus-line" style="font-size: 16px;" title="Bus"></i>'
            };
            return icons[mode] || icons['local'];
        };
        
        // Helper function to get destination display text
        const getDestinationText = (transfer) => {
            // Check if this is a hotel transfer (has hotelName)
            if (transfer.hotelName) {
                return `${transfer.hotelName} / ${transfer.hotelDestination || transfer.destination || ''}`;
            }
            
            const mode = transfer.transportMode || 'local';
            if (mode === 'local') {
                return transfer.destination || (transfer.pickup ? transfer.pickup + ' → ' + transfer.drop : '-');
            } else {
                // For flight, train, bus, cruise
                return (transfer.departFrom || '') + (transfer.destination ? ' → ' + transfer.destination : (transfer.arrivalTo ? ' → ' + transfer.arrivalTo : ''));
            }
        };
        
        // Helper function to get vehicle/transport type
        const getVehicleType = (transfer) => {
            const mode = transfer.transportMode || 'local';
            if (mode === 'local') {
                // Return the vehicle name if available, otherwise vehicle type
                if (transfer.vehicleName && transfer.vehicleName !== '-') {
                    return transfer.vehicleName;
                }
                const vehicleType = transfer.vehicleType || '-';
                if (vehicleType === '-') return '-';
                // Capitalize first letter
                return vehicleType.charAt(0).toUpperCase() + vehicleType.slice(1);
            } else if (mode === 'flight') {
                return transfer.airline || transfer.operator || '-';
            } else if (mode === 'cruise') {
                return transfer.vessel || transfer.by || '-';
            } else if (mode === 'train' || mode === 'bus') {
                return transfer.operator || '-';
            }
            return '-';
        };
        
        // Helper function to get type/class
        const getTypeClass = (transfer) => {
            const mode = transfer.transportMode || 'local';
            if (mode === 'local') {
                const type = transfer.type || '-';
                if (type === '-') return '-';
                // Format the type properly
                if (type === 'S' || type === 'sic') return 'Shared';
                if (type === 'P' || type === 'private') return 'Private';
                return type.charAt(0).toUpperCase() + type.slice(1);
            } else {
                return transfer.class || transfer.cabinClass || '-';
            }
        };
        
        // Helper function to get way/trip type
        const getWayType = (transfer) => {
            const mode = transfer.transportMode || 'local';
            if (mode === 'local') {
                const way = transfer.way || '-';
                if (way === '-') return '-';
                // Format the way properly
                if (way === 'one-way') return 'One Way';
                if (way === 'both-way') return 'Both Way';
                return way;
            } else {
                return transfer.tripType || '-';
            }
        };
        
        tbody.innerHTML = transferList.map((transfer, index) => {
            // Determine display name based on source
            let displayName = '';
            if (transfer.isStandalone) {
                // For standalone transfers, show pickup → drop
                displayName = transfer.destination || `${transfer.pickupName || '-'} → ${transfer.dropName || '-'}`;
            } else if (transfer.service) {
                // For hotel transfers or other services with service field
                // Use the service field which has format "Hotel Name / Destination"
                displayName = transfer.service;
            } else if (transfer.destination) {
                // For attraction/restaurant transfers - show the destination name
                displayName = transfer.destination;
            } else {
                // For transfers from other services (arrival/departure)
                displayName = transfer.portName || '-';
            }
            
            // Ensure dateTime has time component, if not add default time 09:00
            let dateTimeValue = transfer.dateTime || '';
            if (dateTimeValue && !dateTimeValue.includes('T')) {
                dateTimeValue = dateTimeValue + 'T09:00';
            }
            
            // Show checkbox for all transfers (both standalone and linked)
            const checkboxHtml = `<input type="checkbox" class="transfer-checkbox" value="${transfer.id}">`;
            
            // Make service name clickable for both standalone and linked transfers
            const serviceHtml = `<a href="javascript:void(0)" onclick="editTransfer(${index})" style="color: #0d6efd; text-decoration: underline; cursor: pointer;">${displayName || '-'}</a>`;
            
            // Get adult and child values - support both field name formats
            const adults = transfer.adults || transfer.adultsQty || 0;
            const child = transfer.child || transfer.childQty || 0;
            
            // Determine supplement checkbox display - show checkbox for linked transfers too
            const supplementCheckboxHtml = transfer.isStandalone 
                ? `<input type="checkbox" ${transfer.supplement ? 'checked' : ''} onchange="updateTransferSupplement(${index}, this.checked)">`
                : `<input type="checkbox" ${transfer.supplement ? 'checked' : ''} onchange="updateTransferSupplement(${index}, this.checked)" style="opacity: 0.7;">`;
            
            // Normalize pricing using zone rates, type, and way
            const pricing = getLocalTransferPricing(transfer);
            const storedSell = parseFloat(transfer.sell || 0);
            const storedCost = parseFloat(transfer.cost || 0);
            
            let displayCost = pricing.totalPrice;
            if (displayCost === 0 && storedCost > 0) {
                displayCost = storedCost * pricing.wayMultiplier;
            }
            
            // Default to computed total; honor manual sell overrides when present
            let displaySell = pricing.totalPrice;
            if (storedSell > 0 && storedSell !== storedCost) {
                displaySell = storedSell * pricing.wayMultiplier;
            } else if (displaySell === 0 && storedCost > 0) {
                displaySell = storedCost * pricing.wayMultiplier;
            }
            
            return `
            <tr>
                <td>${checkboxHtml}</td>
                <td><input type="datetime-local" value="${dateTimeValue}" onchange="updateTransferField(${index}, 'dateTime', this.value)" style="width: 130px; font-size: 11px; padding: 2px 4px;"></td>
                <td>
                    ${serviceHtml}
                </td>
                <td>${getModeIcon(transfer.transportMode || 'local')}</td>
                <td>${getVehicleType(transfer)}</td>
                <td>${getTypeClass(transfer)}</td>
                <td>${getWayType(transfer)}</td>
                <td><input type="number" value="${adults}" onchange="updateTransferField(${index}, 'adults', this.value)" style="width: 50px;"></td>
                <td><input type="number" value="${child}" onchange="updateTransferField(${index}, 'child', this.value)" style="width: 50px;"></td>
                <td><input type="text" value="${displayCost}" readonly style="width: 70px; background-color: #f5f5f5;"></td>
                <td><input type="number" value="${displaySell}" onchange="updateTransferField(${index}, 'sell', this.value)" step="1" style="width: 70px;"></td>
                <td style="text-align: center;">${supplementCheckboxHtml}</td>
            </tr>
        `;
        }).join('');

        // Ensure footer totals refresh whenever transfer table renders
        recalculateTotals();
    }
    
    // Update transfer field
    function updateTransferField(index, field, value) {
        if (transferList[index]) {
            const transfer = transferList[index];
            transfer[field] = value;
            
            // Also update alternate field names for consistency
            if (field === 'adults') {
                transfer.adultsQty = value;
            } else if (field === 'child') {
                transfer.childQty = value;
            }
            
            // If dateTime field is changed, only expand header dates
            // Do NOT update linked service dates when changing from transfer table
            if (field === 'dateTime' && value) {
                // Always expand header dates only
                expandHeaderDatesIfNeeded(value, false);
                
                // Log the update
                if (transfer.isStandalone) {
                    console.log('Updated standalone transfer date to:', value, '(only header dates updated)');
                } else {
                    console.log('Updated linked transfer date to:', value, '(only header dates updated, source service unchanged)');
                }
                
                // Update the transfer table to reflect the change
                updateTransferTable();
            }
            
            // If sell price, adults, child, type, or way changes for local transfers, recalculate totals
            // This ensures Package Total is updated with new transfer contributions
            if ((field === 'sell' || field === 'adults' || field === 'child' || field === 'type' || field === 'way') && 
                transfer.transportMode === 'local') {
                recalculateTotals();
            }
        }
    }
    
    // Update transfer supplement checkbox
    // Update transfer supplement checkbox - do NOT sync with linked services
    function updateTransferSupplement(index, checked) {
        if (transferList[index]) {
            const transfer = transferList[index];
            transfer.supplement = checked;
            
            // Update the transfer table
            updateTransferTable();
            
            // Recalculate totals after supplement change
            recalculateTotals();
        }
    }
    
    // Open transfer modal (for standalone transfers)
    // Switch between transport mode forms
    function switchTransferMode(mode) {
        // Hide all forms
        document.querySelectorAll('.transfer-mode-form').forEach(form => {
            form.style.display = 'none';
        });
        
        // Show selected form
        const formMap = {
            'local': 'localTransferForm',
            'flight': 'flightForm',
            'cruise': 'cruiseForm',
            'train': 'trainForm',
            'bus': 'busForm'
        };
        
        const formId = formMap[mode];
        if (formId) {
            document.getElementById(formId).style.display = 'block';
        }
    }
    
