                meal_type: meal.mealType || "Breakfast",
                mealSpecificType: meal.mealSpecificType || "🍽️ Buffet",
                mealName: meal.mealName || "",
                meal_name: meal.mealName || "",
                mealId: meal.mealId || "",
                meal_id: meal.mealId || "",
